  version: 1,
  runtime: "rhino",
  description: "Copies list items and adds an alternating boolean flag.",
  properties: {
    items: {
      kind: "expression",
      type: "array",
      description: "Items to annotate."
    }
  },
  outputs: {
    out: {
      type: "array",
      items: {
        type: "object",
        additionalProperties: true,
        properties: {
          alternate: { type: "boolean" }
        }
      }
    }
  }
}

// Use Rhino 1.9.0 features: https://mozilla.github.io/rhino/compat/engines.html
(function () {
  return {
    run: function (ctx, node) {
      var props = ctx.props(node);
      var items = ctx.expr(props.items) || [];
      var output = [];

      for (var i = 0; i < items.length; i++) {
        var source = items[i];
        var copy = {};
        for (var key in source) {
          if (Object.prototype.hasOwnProperty.call(source, key)) {
            copy[key] = source[key];
          }
        }
        copy.alternate = i % 2 === 0;
        output.push(copy);
      }

      return output;
    }
  };
}())

