const _meta = {
  version: 1,
  runtime: "rhino",
  description: "Groups list items into ordered pairs.",
  properties: {
    items: {
      kind: "expression",
      type: "array",
      description: "Items to group in pairs."
    }
  },
  outputs: {
    out: {
      type: "array",
      items: {
        type: "object",
        properties: {
          first: { type: "object", additionalProperties: true },
          second: { type: ["object", "null"], additionalProperties: true }
        }
      }
    }
  }
}

// Use Rhino 1.9.0 features: https://mozilla.github.io/rhino/compat/engines.html
(function () {
  return {
    run: function (ctx, node) {
      var props = ctx.props(node);
      var items = ctx.expr(props.items) || [];
      var rows = [];

      for (var i = 0; i < items.length; i += 2) {
        rows.push({
          first: items[i],
          second: i + 1 < items.length ? items[i + 1] : null
        });
      }

      return rows;
    }
  };
}())

